{"path": "bowling.py", "content": "class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 0       # completed frames (0-9) before the tenth
        self.pending = None  # first roll of the current frame, if any
        self.tenth = []
        self.done = False

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("invalid number of pins")
        if self.done:
            raise IndexError("cannot roll after game is over")
        if self.frame < 9:
            if self.pending is None:
                self.rolls.append(pins)
                if pins == 10:
                    self.frame += 1
                else:
                    self.pending = pins
            else:
                if self.pending + pins > 10:
                    raise ValueError("pin count exceeds pins on the lane")
                self.rolls.append(pins)
                self.pending = None
                self.frame += 1
            return
        t = self.tenth
        if len(t) == 1 and t[0] < 10 and t[0] + pins > 10:
            raise ValueError("pin count exceeds pins on the lane")
        if len(t) == 2 and t[0] == 10 and t[1] < 10 and t[1] + pins > 10:
            raise ValueError("invalid fill balls")
        t.append(pins)
        self.rolls.append(pins)
        if len(t) == 3 or (len(t) == 2 and t[0] + t[1] < 10):
            self.done = True

    def score(self):
        if not self.done:
            raise IndexError("cannot score an incomplete game")
        r = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if r[i] == 10:
                total += 10 + r[i + 1] + r[i + 2]
                i += 1
            elif r[i] + r[i + 1] == 10:
                total += 10 + r[i + 2]
                i += 2
            else:
                total += r[i] + r[i + 1]
                i += 2
        return total
